#!/usr/bin/env python3
"""Package a frozen control run as the sole durable evidence file."""
import argparse
import hashlib
import json
import pathlib
import sys


def sha256_bytes(data):
    return hashlib.sha256(data).hexdigest()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--program-source", required=True)
    parser.add_argument("--program-stdout", required=True)
    parser.add_argument("--program-stderr", required=True)
    parser.add_argument("--program-exit", required=True)
    parser.add_argument("--program-source-sha", required=True)
    parser.add_argument("--packer-source-sha", required=True)
    args = parser.parse_args()

    program_source = pathlib.Path(args.program_source).read_text()
    program_stdout = pathlib.Path(args.program_stdout).read_text()
    program_stderr = pathlib.Path(args.program_stderr).read_text()
    program_exit = int(pathlib.Path(args.program_exit).read_text().strip())
    packer_source = pathlib.Path(__file__).read_text()
    if sha256_bytes(program_source.encode()) != args.program_source_sha:
        raise AssertionError("program source changed after its declared freeze hash")
    if sha256_bytes(packer_source.encode()) != args.packer_source_sha:
        raise AssertionError("packer source changed after its declared freeze hash")
    parsed = json.loads(program_stdout)
    if program_exit != 0 or program_stderr:
        raise AssertionError("the bounded program did not complete cleanly")
    if parsed["program_source_sha256"] != args.program_source_sha:
        raise AssertionError("program result does not bind the frozen source hash")
    N5 = parsed["boxes"]["N5"]
    N6 = parsed["boxes"]["N6"]
    if not (N5["completed_entire_box"] and N6["completed_entire_box"]):
        raise AssertionError("this packer is restricted to the completed-box nonfinding result")
    if N5["failure"] is not None or N6["failure"] is not None:
        raise AssertionError("a failure requires a separate complete certificate package")
    if N5["scanned_tuple_count"] != 1140 or N6["scanned_tuple_count"] != 1820:
        raise AssertionError("tuple counts differ from the settled bounded contract")
    if N5["aggregate_before_stop"]["tuples_with_forward_good_residue"] != 1140:
        raise AssertionError("N5 had a tuple without a forward-good residue")
    if N6["aggregate_before_stop"]["tuples_with_forward_good_residue"] != 1820:
        raise AssertionError("N6 had a tuple without a forward-good residue")

    artifact = {
        "schema": "astra-forward-grid-control-receipt-v1",
        "scope": {
            "claim": "One bounded exact falsification control of the settled uniform adapted-grid insertion mechanism.",
            "nonclaim": "This nonfinding neither proves the uniform mechanism nor addresses the unrestricted Lonely Runner Conjecture.",
            "expansion": "None. The control stops after the two specified boxes because neither contains a failure.",
        },
        "source_checkpoint": parsed["source_checkpoint"],
        "settled_contract": parsed["settled_contract"],
        "execution": {
            "elapsed_seconds": parsed["execution"]["program_elapsed_seconds"],
            "stop_rule": parsed["execution"]["stop_rule"],
        },
        "frozen_execution": {
            "program": {
                "path": args.program_source,
                "sha256": args.program_source_sha,
                "source": program_source,
                "argv": ["python3"] + parsed["program_argv"],
                "outer_command": "python3 /tmp/astra-forward-grid-control.py --source-sha f2c2ccb69583bf91bf4a0dfbf8e705da3b0af80d6aafaac1751a996c348aa62b > /tmp/astra-forward-grid-control.stdout 2> /tmp/astra-forward-grid-control.stderr",
                "exit_status": program_exit,
                "stdout": program_stdout,
                "stderr": program_stderr,
                "stdout_bytes": len(program_stdout.encode()),
                "stderr_bytes": len(program_stderr.encode()),
                "program_elapsed_seconds": parsed["execution"]["program_elapsed_seconds"],
            },
            "packer": {
                "path": str(pathlib.Path(__file__)),
                "sha256": args.packer_source_sha,
                "source": packer_source,
                "argv": ["python3"] + sys.argv,
                "role": "Reads the frozen program receipt, validates the prescribed completed-box nonfinding invariants, and emits this apply_patch artifact; it does not search tuples.",
            },
        },
        "predicate_contract": parsed["predicate_contract"],
        "result": {
            "status": "bounded_nonfinding",
            "boxes": parsed["boxes"],
            "failure_certificate": None,
            "lrc_witness_control": {
                "status": "not_applicable",
                "reason": "No old tuple failed the forward predicate, so no auxiliary appended-grid failure existed to distinguish from an ordinary LRC witness.",
            },
        },
        "verification": {
            "exact_sumset_residues": "The program constructs unique residues modulo D through the required iterative digit sumsets.",
            "Fraction_cross_check": "For every tested residue, the program asserts agreement between the integer predicate and an independently computed Fraction phase predicate.",
            "full_grid_direct_check": "Not applicable: no old failure triggered construction of w=D*M or a full-grid candidate set.",
            "fraction_witness_search": "Not applicable: the specified old-band/fast-band witness control runs only for an auxiliary-grid failure.",
            "workflow_validation": "python3 scripts/validate_workflow.py exited 0 before execution: workflow structural validation passed; it cannot certify mathematical validity.",
        },
        "delivery_metrics": {
            "check_kind": "python",
            "first_check_success": True,
            "worker_repair_rounds": 0,
            "astra_repair_rounds": 0,
            "astra_repair_lines": 0,
            "worker_elapsed_seconds": None,
            "usage": None,
            "program_elapsed_seconds": parsed["execution"]["program_elapsed_seconds"],
        },
    }
    payload = json.dumps(artifact, indent=2, sort_keys=True) + "\n"
    lines = payload.splitlines()
    print("*** Begin Patch")
    print("*** Add File: research/astra-forward-grid-control.json")
    for line in lines:
        print("+" + line)
    print("*** End Patch")


if __name__ == "__main__":
    main()

