#!/usr/bin/env python3
"""Exact bounded control for the settled forward-grid insertion contract."""
import argparse
import itertools
import json
import math
import sys
import time
from fractions import Fraction


def fraction_record(value):
    return {"numerator": value.numerator, "denominator": value.denominator}


def phase_fraction(speed, numerator, denominator):
    return Fraction((speed * numerator) % denominator, denominator)


def old_point_record(N, values, L, D, x):
    residues = []
    violating = []
    integer_forward_good = True
    fraction_forward_good = True
    for index, speed in enumerate(values):
        residue = (speed * x) % D
        integer_good = L <= residue < D - L
        phase = phase_fraction(speed, x, D)
        fraction_good = Fraction(1, N) <= phase < Fraction(N - 1, N)
        if integer_good != fraction_good:
            raise AssertionError("old integer and Fraction predicates disagree")
        residues.append({
            "label": index,
            "speed": speed,
            "residue": residue,
            "phase": fraction_record(phase),
            "integer_forward_good": integer_good,
            "fraction_forward_good": fraction_good,
        })
        if not integer_good:
            violating.append(index)
            integer_forward_good = False
        if not fraction_good:
            fraction_forward_good = False
    if integer_forward_good != fraction_forward_good:
        raise AssertionError("old point aggregate predicates disagree")
    return {
        "x": x,
        "residues": residues,
        "violating_labels": violating,
        "integer_forward_good": integer_forward_good,
        "fraction_forward_good": fraction_forward_good,
    }


def full_point_record(N, appended_values, w, E, B):
    residues = []
    violating = []
    integer_closed_good = True
    fraction_closed_good = True
    for index, speed in enumerate(appended_values):
        residue = (speed * B) % E
        integer_good = w <= residue <= (N - 1) * w
        phase = phase_fraction(speed, B, E)
        fraction_good = Fraction(1, N) <= phase <= Fraction(N - 1, N)
        if integer_good != fraction_good:
            raise AssertionError("full integer and Fraction predicates disagree")
        residues.append({
            "label": index,
            "speed": speed,
            "residue": residue,
            "phase": fraction_record(phase),
            "integer_closed_good": integer_good,
            "fraction_closed_good": fraction_good,
        })
        if not integer_good:
            violating.append(index)
            integer_closed_good = False
        if not fraction_good:
            fraction_closed_good = False
    if integer_closed_good != fraction_closed_good:
        raise AssertionError("full point aggregate predicates disagree")
    return {
        "B": B,
        "residues": residues,
        "violating_labels": violating,
        "integer_closed_good": integer_closed_good,
        "fraction_closed_good": fraction_closed_good,
    }


def unique_residues(N, values, L, D):
    points = {0}
    factors = [L // value for value in values]
    for factor in factors:
        points = {(point + digit * factor) % D for point in points for digit in range(N)}
    return sorted(points), factors


def closed_good_fraction(N, speed, time_value):
    phase = (speed * time_value) % 1
    return Fraction(1, N) <= phase <= Fraction(N - 1, N), phase


def full_witness(N, values, w):
    boundaries = {Fraction(0), Fraction(1)}
    for speed in values:
        for k in range(speed + 1):
            for sign in (-1, 1):
                boundary = Fraction(N * k + sign, N * speed)
                if Fraction(0) <= boundary <= Fraction(1):
                    boundaries.add(boundary)
    ordered = sorted(boundaries)
    good_bands = []
    for left, right in zip(ordered, ordered[1:]):
        midpoint = (left + right) / 2
        midpoint_checks = []
        all_good = True
        for index, speed in enumerate(values):
            good, phase = closed_good_fraction(N, speed, midpoint)
            midpoint_checks.append({
                "label": index,
                "speed": speed,
                "phase": fraction_record(phase),
                "closed_good": good,
            })
            all_good = all_good and good
        if all_good and midpoint > 0:
            good_bands.append({
                "left": fraction_record(left),
                "right": fraction_record(right),
                "midpoint": fraction_record(midpoint),
                "midpoint_checks": midpoint_checks,
            })

    attempts = []
    for band_index, band in enumerate(good_bands):
        left = Fraction(band["left"]["numerator"], band["left"]["denominator"])
        right = Fraction(band["right"]["numerator"], band["right"]["denominator"])
        z0 = (w * left.numerator) // left.denominator
        for z in (z0, z0 + 1):
            lower = Fraction(N * z + 1, N * w)
            upper = Fraction(N * z + N - 1, N * w)
            candidate = max(left, lower)
            interval_nonempty = candidate <= upper and candidate <= right
            attempt = {
                "band_index": band_index,
                "z": z,
                "fast_lower": fraction_record(lower),
                "fast_upper": fraction_record(upper),
                "candidate": fraction_record(candidate),
                "candidate_within_old_band_and_fast_band": interval_nonempty,
            }
            if interval_nonempty:
                checks = []
                all_good = True
                for index, speed in enumerate(values + [w]):
                    good, phase = closed_good_fraction(N, speed, candidate)
                    checks.append({
                        "label": index,
                        "speed": speed,
                        "phase": fraction_record(phase),
                        "closed_good": good,
                    })
                    all_good = all_good and good
                attempt["all_phase_checks"] = checks
                attempt["fraction_witness_verified"] = all_good
                if all_good:
                    attempts.append(attempt)
                    return {
                        "status": "witness_found",
                        "boundary_count": len(ordered),
                        "boundaries": [fraction_record(boundary) for boundary in ordered],
                        "old_good_bands": good_bands,
                        "candidate_attempts": attempts,
                        "witness": {
                            "time": fraction_record(candidate),
                            "band_index": band_index,
                            "z": z,
                            "all_phase_checks": checks,
                        },
                    }
            attempts.append(attempt)
    return {
        "status": "unavailable",
        "blocker": "No candidate from the specified z=floor(w*a) and z+1 checks was Fraction-verified inside an old-good band and a fast-good band.",
        "boundary_count": len(ordered),
        "boundaries": [fraction_record(boundary) for boundary in ordered],
        "old_good_bands": good_bands,
        "candidate_attempts": attempts,
    }


def failure_certificate(N, values, L, M, D, points, factors):
    old_points = [old_point_record(N, values, L, D, x) for x in points]
    if any(record["integer_forward_good"] for record in old_points):
        raise AssertionError("failure certificate called for a forward-good residue")
    if any(not record["violating_labels"] for record in old_points):
        raise AssertionError("a failing old point needs a violating label")
    w = D * M
    E = N * w
    appended_values = list(values) + [w]
    B_points = sorted({((w // L) * x + ell) % E for x in points for ell in range(N)})
    expected_B_count = len(points) * N
    if len(B_points) != expected_B_count:
        raise AssertionError("the x,ell construction unexpectedly collided")
    full_points = [full_point_record(N, appended_values, w, E, B) for B in B_points]
    if any(record["integer_closed_good"] for record in full_points):
        raise AssertionError("an appended grid point passed the closed condition")
    if any(not record["violating_labels"] for record in full_points):
        raise AssertionError("a failing full point needs a violating label")
    witness = full_witness(N, list(values), w)
    return {
        "tuple": list(values),
        "N": N,
        "L": L,
        "M": M,
        "D": D,
        "sumset_factors": factors,
        "old_unique_residue_count": len(points),
        "old_unique_residues": points,
        "old_failure_certificate": old_points,
        "appended_speed_w": w,
        "E": E,
        "full_unique_point_count": len(B_points),
        "full_unique_points": B_points,
        "full_failure_certificate": full_points,
        "direct_full_closed_failure_fraction_verified": True,
        "lrc_witness_control": witness,
    }


def screen_box(N, upper):
    expected_count = math.comb(upper, N - 2)
    scanned = 0
    first_failure = None
    first_success = None
    aggregate = {
        "tuples_with_forward_good_residue": 0,
        "total_unique_old_residues": 0,
        "total_forward_good_unique_residues": 0,
    }
    for values in itertools.combinations(range(1, upper + 1), N - 2):
        scanned += 1
        L = math.lcm(*values)
        M = max(values)
        D = N * L
        points, factors = unique_residues(N, values, L, D)
        old_records = [old_point_record(N, values, L, D, x) for x in points]
        forward_good = [record["x"] for record in old_records if record["integer_forward_good"]]
        aggregate["total_unique_old_residues"] += len(points)
        aggregate["total_forward_good_unique_residues"] += len(forward_good)
        if forward_good:
            aggregate["tuples_with_forward_good_residue"] += 1
            if first_success is None:
                first_success = {"tuple": list(values), "first_forward_good_x": forward_good[0]}
            continue
        first_failure = failure_certificate(N, values, L, M, D, points, factors)
        break
    result = {
        "N": N,
        "increasing_tuple_domain": {"minimum": 1, "maximum": upper, "length": N - 2},
        "expected_tuple_count": expected_count,
        "scanned_tuple_count": scanned,
        "completed_entire_box": scanned == expected_count,
        "aggregate_before_stop": aggregate,
        "first_forward_good_control": first_success,
        "failure": first_failure,
    }
    return result


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--source-sha", required=True)
    args = parser.parse_args()
    started = time.monotonic()
    N5 = screen_box(5, 20)
    if N5["failure"] is None:
        N6 = screen_box(6, 16)
    else:
        N6 = {
            "status": "not_run_after_N5_first_failure",
            "reason": "The bounded contract requires stopping at the first tuple with no forward-good assignment.",
        }
    duration = time.monotonic() - started
    output = {
        "schema": "astra-forward-grid-control-v1",
        "source_checkpoint": "600287d55a01d3c8c2d3bf4e4114eee4f9c1271e",
        "settled_contract": {
            "research/astra-forward-grid-insertion.md": "b1185bc69414dbb6dfa36bc04ed2a80f92b75856867190015b19c53216babb33",
            "research/astra-forward-grid-insertion-review.md": "ba90a5a4fa2cb6e767a2c85d8b6d6c4a9d0d1a54bdc47e5f4c870591138adb82",
        },
        "program_source_sha256": args.source_sha,
        "program_argv": sys.argv,
        "predicate_contract": {
            "old_unique_x": "sumsets of k*(L//v_i), k=0,...,N-1, reduced modulo D=N*L",
            "forward_good": "for every old v_i: L <= (v_i*x) mod D < D-L",
            "full_unique_B": "B=((w//L)*x+ell) mod E, ell=0,...,N-1, with w=D*M and E=N*w",
            "closed_good": "for every appended speed u: w <= (u*B) mod E <= (N-1)*w",
            "independent_check": "Every listed old and full residue is checked again as a Fraction phase against the corresponding half-open or closed band.",
        },
        "boxes": {"N5": N5, "N6": N6},
        "execution": {
            "program_elapsed_seconds": duration,
            "stop_rule": "N5 then N6; stop at the first tuple with no forward-good assignment; do not expand either box.",
        },
    }
    print(json.dumps(output, sort_keys=True, separators=(",", ":")))


if __name__ == "__main__":
    main()
